    }
    Node* update(std::int64_t k, const T& value) { return update(root, k, value); }
private:
    T get_unchecked(Node* n, std::int64_t k) const {
        const auto index = static_cast<std::uint64_t>(k);
        for (int d = levels_; d > 0; --d) {
            if (!n) return storage_->id;
