from pathlib import Path
p=Path(__file__).parent;base=(p.parent/'baseline/DataStructure/persistent-union-find.cpp').read_text()
(p/'baseline.hpp').write_text(base);(p/'control.hpp').write_text(base)
pair_helper='''    Node* update_one(Node* base, std::uint64_t index, const T& value, int level) {
        Node* result = allocate(base, level == 0);
        if (level == 0) std::get<1>(result->content)[index & (width - 1)] = value;
        else {
            auto& child = std::get<0>(result->content)[(index >> (level * shift)) & (width - 1)];
            child = update_one(child, index, value, level - 1);
        }
        return result;
    }
    Node* update_two(Node* base, std::uint64_t a, const T& x, std::uint64_t b, const T& y, int level) {
        Node* result = allocate(base, level == 0);
        if (level == 0) {
            auto& values = std::get<1>(result->content);
            values[a & (width - 1)] = x;
            values[b & (width - 1)] = y;
        } else {
            const auto sa = (a >> (level * shift)) & (width - 1);
            const auto sb = (b >> (level * shift)) & (width - 1);
            auto& children = std::get<0>(result->content);
            if (sa == sb) children[sa] = update_two(children[sa], a, x, b, y, level - 1);
            else {
                children[sa] = update_one(children[sa], a, x, level - 1);
                children[sb] = update_one(children[sb], b, y, level - 1);
            }
        }
        return result;
    }
'''
old='''        const auto old = arr.root;
        try { r = arr.update(r, a, sa + sb); r = arr.update(r, b, a); }
        catch (...) { arr.root = old; throw; }
        root = r; return true;'''
new='''        r = arr.update_two(r, static_cast<std::uint64_t>(a), sa + sb,
                           static_cast<std::uint64_t>(b), a, arr.levels_);
        root = arr.root = r; return true;'''
pair=base.replace('private:\n    T get_unchecked', 'private:\n'+pair_helper+'    T get_unchecked').replace(old,new)
assert pair!=base;(p/'pair.hpp').write_text(pair)
for count in [32,128,512,2048]:
 old_storage='    struct Storage { T id; std::deque<Node> nodes; explicit Storage(T value) : id(std::move(value)) {} };'
 new_storage='''    struct Storage {
        T id;
        std::vector<std::vector<Node>> blocks;
        std::size_t node_count = 0;
        explicit Storage(T value) : id(std::move(value)) {}
    };'''
 old_alloc='''        if (storage_->nodes.size() == storage_->nodes.max_size())
            throw std::length_error("PersistentArray: node capacity");
        if (original) storage_->nodes.emplace_back(*original);
        else storage_->nodes.emplace_back(leaf, storage_->id, storage_.get());
        return &storage_->nodes.back();'''
 new_alloc=f'''        if (storage_->node_count == std::numeric_limits<std::size_t>::max())
            throw std::length_error("PersistentArray: node capacity");
        if (storage_->blocks.empty() || storage_->blocks.back().size() == storage_->blocks.back().capacity()) {{
            std::vector<Node> block;
            block.reserve({count});
            storage_->blocks.push_back(std::move(block));
        }}
        auto& block = storage_->blocks.back();
        if (original) block.emplace_back(*original);
        else block.emplace_back(leaf, storage_->id, storage_.get());
        ++storage_->node_count;
        return &block.back();'''
 for name,source in [('block',base),('pairblock',pair)]:
  s=source.replace(old_storage,new_storage).replace(old_alloc,new_alloc)
  assert s!=source;(p/f'{name}{count}.hpp').write_text(s)
print('candidates prepared')

