from pathlib import Path
p=Path(__file__).parent
helper='''    Node* update_one(Node* base, std::uint64_t index, const T& value, int level) {
        Node* result = allocate(base, level == 0);
        Node* current = result;
        for (int d = level; d > 0; --d) {
            auto& child = std::get<0>(current->content)[(index >> (d * shift)) & (width - 1)];
            child = allocate(child, d == 1);
            current = child;
        }
        std::get<1>(current->content)[index & (width - 1)] = value;
        return result;
    }
    Node* update_two(Node* base, std::uint64_t a, const T& x, std::uint64_t b, const T& y, int level) {
        Node* result = allocate(base, level == 0);
        Node* current = result;
        for (int d = level; d > 0; --d) {
            const auto sa = (a >> (d * shift)) & (width - 1);
            const auto sb = (b >> (d * shift)) & (width - 1);
            auto& children = std::get<0>(current->content);
            if (sa != sb) {
                children[sa] = update_one(children[sa], a, x, d - 1);
                children[sb] = update_one(children[sb], b, y, d - 1);
                return result;
            }
            children[sa] = allocate(children[sa], d == 1);
            current = children[sa];
        }
        auto& values = std::get<1>(current->content);
        values[a & (width - 1)] = x;
        values[b & (width - 1)] = y;
        return result;
    }
'''
for n in ['pair','pairblock512','pairblockadaptive512']:
 s=(p/(n+'.hpp')).read_text();start=s.index('    Node* update_one(');end=s.index('    T get_unchecked(',start);s=s[:start]+helper+s[end:];(p/(n.replace('pair','pairiter',1)+'.hpp')).write_text(s)

