 for(std::size_t j=0;j<roots.size();j+=97){uf.restore(roots[j]);auto cp=uf;assert(cp.root==uf.root);if(n){cp.unite(0,n-1);assert(uf.root==roots[j]);}auto moved=std::move(cp);assert(cp.size()==0&&cp.root==nullptr);assert(moved.size()==n);++checks;}}
