#include <cstdio>
#include <new>
#include <chrono>
static bool track=false;static std::size_t calls=0,bytes=0;static const void*volatile escaped=nullptr;
void*operator new(std::size_t n){if(track){++calls;bytes+=n;}if(void*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
int main(int argc,char**argv){if(argc!=3)return 1;const int n=std::atoi(argv[1]),repeats=std::atoi(argv[2]);std::size_t checksum=0;track=true;auto start=std::chrono::steady_clock::now();for(int i=0;i<repeats;++i){PersistentUnionFind uf(n);escaped=uf.root;checksum+=uf.size();if(n)checksum+=uf.size(i%n);}auto end=std::chrono::steady_clock::now();track=false;std::printf("%jd %zu %zu %zu %zu\n",static_cast<std::intmax_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(end-start).count()),checksum,calls,bytes,sizeof(PersistentUnionFind::Node));}

