#include HEADER
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <chrono>
#include <random>
#include <vector>
struct Op{std::int64_t a,b;int x,y;};
int main(int argc,char**argv){if(argc!=5)return 1;int mode=std::atoi(argv[1]),n=std::atoi(argv[2]),pattern=std::atoi(argv[3]),branch=std::atoi(argv[4]);const int steps=50000;std::mt19937 rng(13141);std::vector<Op> ops;ops.reserve(steps);for(int i=0;i<steps;++i){std::int64_t a=rng()%n,b=pattern==0?a:pattern==1?((a/16)*16+(rng()%16))%n:rng()%n;ops.push_back({a,b,i+1,-i-1});}
 std::vector<PersistentArray<int>::Node*> roots;roots.reserve(steps);PersistentArray<int> array(n,0);auto initial=array.root;auto start=std::chrono::steady_clock::now();for(const auto&op:ops){auto base=branch?initial:array.root;if(mode==0){array.update(base,op.a,op.x);array.update(op.b,op.y);}else array.update_two(base,op.a,op.x,op.b,op.y);roots.push_back(array.root);}auto end=std::chrono::steady_clock::now();std::uint64_t checksum=0;for(int k=0;k<steps;k+=97){const auto&op=ops[k];int a=array.get(roots[k],op.a),b=array.get(roots[k],op.b);if(b!=op.y||(op.a!=op.b&&a!=op.x)||(op.a==op.b&&a!=op.y))return 2;checksum+=static_cast<std::uint32_t>(a)+static_cast<std::uint64_t>(static_cast<std::uint32_t>(b));}if(array.get(initial,0)!=0)return 3;std::printf("%jd %ju\n",static_cast<std::intmax_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(end-start).count()),static_cast<std::uintmax_t>(checksum));}

