def collect(folder,label):
 for f in folder.glob('*.hpp'):
  h=sha(f.read_bytes());d=pool.setdefault(h,dict(sha256=h,names=[],stages=[],source=f.read_text()));d['names']=sorted(set(d['names']+[f.name]));d['stages']=sorted(set(d['stages']+[label]))
