  shutil.copy2(p/script,folder/script);subprocess.run(['python3',str(folder/script)],check=True,capture_output=True)
 collect(folder,stage)
collect(p,'final_candidates_after_copy_only_fix');collect(p.parent/'final_performance','final_measurement')
# Full translation units preserve exact benchmark headers even if candidates were later revised.
for name in ['bench','finalists']:
 for f in (p/name).glob('*.cpp'):
  s=f.read_text();assert s.startswith('#define SKIP_RUNTIME_CHECKS\n');main=(p.parent/'baseline/Verify/current/drivers/persistent_union_find_main.cpp').read_text().replace('#include "Verify/current/common/fast_io.hpp"',(p.parent/'baseline/Verify/current/common/fast_io.hpp').read_text());assert s.endswith('\n'+main);header=s[len('#define SKIP_RUNTIME_CHECKS\n'):-len('\n'+main)];h=sha(header.encode());d=pool.setdefault(h,dict(sha256=h,names=[],stages=[],source=header));d['names']=sorted(set(d['names']+[f.name]));d['stages']=sorted(set(d['stages']+[name+'_measurement']))
missing=[]
for n in ['checks.json','more_checks.json','selected_checks.json']:
 d=json.loads((p/n).read_text())
 for x in d['results']:
  if x['header_sha256']not in pool:missing.append((n,x['header'],x['header_sha256']))
assert not missing,missing
for h,d in pool.items():(history/(h+'.hpp')).write_text(d['source'])
(history/'index.json').write_text(json.dumps(pool,ensure_ascii=False,indent=2)+'\n');print('history',len(pool),'sources; all checked SHA matched')

